type SettledResult = { status: 'fulfilled'; value: any } | { status: 'rejected'; reason: any };

function promiseAllSettled(functions: Function[]): Promise<SettledResult[]> {
    return new Promise((resolve) => {
        if (functions.length === 0) {
            resolve([]);
            return;
        }
        const results: SettledResult[] = new Array(functions.length);
        let settledCount = 0;
        functions.forEach((fn, idx) => {
            fn()
                .then((value: any) => {
                    results[idx] = { status: 'fulfilled', value };
                })
                .catch((reason: any) => {
                    results[idx] = { status: 'rejected', reason };
                })
                .finally(() => {
                    settledCount++;
                    if (settledCount === functions.length) {
                        resolve(results);
                    }
                });
        });
    });
}
